                            label: "Last Active",
                            value: formatTimeAgo(session.timeSinceLastActivity)
                        )
                    }

                    // Tools used
                    if !session.toolsUsed.isEmpty {
                        VStack(alignment: .leading, spacing: DesignTokens.Spacing.xs) {
