                                        .font(DesignTokens.Typography.caption)
                                        .padding(.horizontal, DesignTokens.Spacing.xs)
                                        .padding(.vertical, 2)
                                        .background(DesignTokens.Colors.cardBackground)
                                        .clipShape(RoundedRectangle(cornerRadius: 4))
                                }
                            }
                        }
