        let config = PrioritySchedulerConfig::default();
        let mut scheduler = PriorityScheduler::new(config);

        // Submit two tasks for the same domain
        scheduler.submit(
            "task1".to_string(),
            TaskMetadata::new(
                PriorityTier::User,
                Some("example.com".to_string()),
                RiskLevel::High,
            ),
        );
        scheduler.submit(
            "task2".to_string(),
