/// Detect if a task is a browser task
pub fn is_browser_task(task: &Task) -> bool {
    matches!(
        task.task_type,
        TaskType::BrowserAction { .. } | TaskType::WebScraping { .. }
    )
}

/// Extract task metadata for priority scheduling
pub fn extract_task_metadata(task: &Task) -> TaskMetadata {
    // Determine priority tier based on task type
    let tier = match &task.task_type {
        // User-initiated actions get highest priority
        TaskType::BrowserAction { .. } => PriorityTier::User,

        // Financial operations get high priority
        TaskType::WebScraping { .. } if task.description.contains("financial") => {
            PriorityTier::Financial
        }

        // Everything else is background
        _ => PriorityTier::Background,
    };

    // Extract domain from task metadata
    let domain = extract_domain_from_task(task);

    // Determine risk level
    let risk_level = determine_risk_level(task);

    TaskMetadata::new(tier, domain, risk_level)
}

/// Extract domain from task
fn extract_domain_from_task(task: &Task) -> Option<String> {
    // Try to extract domain from task description or metadata
    // This is a simplified implementation
    match &task.task_type {
        TaskType::BrowserAction { .. } | TaskType::WebScraping { .. } => {
            // In a real implementation, this would parse the URL from task metadata
            // For now, return None to indicate no domain restriction
            None
        }
        _ => None,
    }
}

/// Determine risk level for a task
fn determine_risk_level(task: &Task) -> RiskLevel {
    match &task.task_type {
        TaskType::BrowserAction { .. } => {
            // Check if task involves financial operations or data modification
            if task.description.contains("payment")
                || task.description.contains("transaction")
                || task.description.contains("transfer")
            {
                RiskLevel::High
            } else if task.description.contains("form")
                || task.description.contains("submit")
                || task.description.contains("login")
            {
                RiskLevel::Medium
            } else {
                RiskLevel::Low
            }
        }
        TaskType::WebScraping { .. } => RiskLevel::Low,
        _ => RiskLevel::Low,
    }
}

