/// 单个补丁：描述如何修改文件的一部分
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Patch {
    /// 起始行号（1-indexed，inclusive）
    pub start_line: usize,

    /// 结束行号（1-indexed，inclusive）
    pub end_line: usize,

    /// 原始内容（用于验证，防止并发修改冲突）
    pub old_content: String,

    /// 新内容（替换 start_line 到 end_line 的内容）
    pub new_content: String,
}

impl Patch {
    /// 验证补丁是否适用于给定的文件内容
    pub fn validate(&self, file_content: &str) -> Result<()> {
        let lines: Vec<&str> = file_content.lines().collect();

        // 检查行号范围
        if self.start_line == 0 || self.start_line > lines.len() {
            return Err(anyhow!("Invalid start_line: {}", self.start_line));
        }
        if self.end_line < self.start_line || self.end_line > lines.len() {
            return Err(anyhow!("Invalid end_line: {}", self.end_line));
        }

        // 提取实际内容
        let actual_content = lines[(self.start_line - 1)..self.end_line]
            .join("\n");

        // 验证 old_content 是否匹配
        if actual_content != self.old_content {
            return Err(anyhow!(
                "Patch validation failed: content mismatch at lines {}-{}\n\
                 Expected:\n{}\n\nActual:\n{}",
                self.start_line, self.end_line,
                self.old_content, actual_content
            ));
        }

        Ok(())
    }

    /// 应用补丁到文件内容
    pub fn apply(&self, file_content: &str) -> Result<String> {
        self.validate(file_content)?;

        let mut lines: Vec<&str> = file_content.lines().collect();

        // 替换指定行
        let new_lines: Vec<&str> = self.new_content.lines().collect();
        lines.splice(
            (self.start_line - 1)..self.end_line,
            new_lines.iter().copied()
        );

        Ok(lines.join("\n"))
    }
}
```

### 4.3 多补丁应用策略

```rust
/// 补丁应用器：处理多个补丁的顺序应用
pub struct PatchApplier {
    patches: Vec<Patch>,
}

impl PatchApplier {
    pub fn new(patches: Vec<Patch>) -> Self {
        Self { patches }
    }

    /// 应用所有补丁（按行号排序，从后往前应用）
    pub fn apply_all(&self, file_content: &str) -> Result<String> {
        // 关键：从后往前应用，避免行号偏移问题
        let mut sorted_patches = self.patches.clone();
        sorted_patches.sort_by(|a, b| b.start_line.cmp(&a.start_line));

        let mut result = file_content.to_string();
        for patch in sorted_patches {
            result = patch.apply(&result)?;
        }

        Ok(result)
    }

    /// 检测补丁冲突（重叠的行范围）
    pub fn detect_conflicts(&self) -> Vec<(usize, usize)> {
        let mut conflicts = Vec::new();

        for i in 0..self.patches.len() {
            for j in (i + 1)..self.patches.len() {
                let p1 = &self.patches[i];
                let p2 = &self.patches[j];

                // 检查行范围是否重叠
                if p1.start_line <= p2.end_line && p2.start_line <= p1.end_line {
                    conflicts.push((i, j));
                }
            }
        }

        conflicts
    }
}
```

**设计要点**：
- **验证机制**：通过 `old_content` 验证，防止并发修改导致的错误应用
- **从后往前应用**：避免前面的补丁改变后面补丁的行号
- **冲突检测**：在应用前检测重叠的补丁，提前报错

