## 6. PiEngine 主体设计

### 6.1 核心结构

```rust
// core/src/pi/engine.rs

/// Pi 引擎：整合反射层、推理层和执行层
pub struct PiEngine {
    /// 反射层（L1/L2 快速路由）
    reflex: Arc<ReflexLayer>,

    /// 推理引擎（L3 LLM 推理）
    reasoning: Arc<dyn ReasoningEngine>,

    /// 原子执行器
    executor: Arc<AtomicExecutor>,

    /// 配置
    config: PiConfig,
}

#[derive(Debug, Clone)]
pub struct PiConfig {
    /// 是否启用反射层
    pub enable_reflex: bool,

    /// 是否启用自学习
    pub enable_learning: bool,

    /// 最大重试次数（自愈循环）
    pub max_retries: usize,

    /// 是否启用详细日志
    pub verbose: bool,
}
```

### 6.2 核心执行流程

```rust
impl PiEngine {
    /// 主执行入口
    pub async fn execute(&self, input: &str, context: &ExecutionContext) -> Result<ExecutionResult> {
        let start = Instant::now();

        // Step 1: 尝试反射层（L1/L2）
        if self.config.enable_reflex {
            if let Some(action) = self.reflex.try_reflex(input) {
                let result = self.executor.execute_atomic(&action, context).await?;

                return Ok(ExecutionResult {
                    output: result,
                    route: ExecutionRoute::Reflex,
                    duration: start.elapsed(),
                });
            }
        }

        // Step 2: 进入推理层（L3）
        let decision = self.reasoning.reason(input, context).await?;
        let action = self.decision_to_atomic(&decision)?;

        // Step 3: 执行原子操作
        let result = self.executor.execute_atomic(&action, context).await?;

        // Step 4: 自学习（将成功的推理加入反射层）
        if self.config.enable_learning && result.is_success() {
            self.reflex.learn_from_success(input, action.clone());
        }

        Ok(ExecutionResult {
            output: result,
            route: ExecutionRoute::Reasoning,
            duration: start.elapsed(),
        })
    }

    /// 带自愈能力的执行（核心创新）
    pub async fn execute_with_healing(
        &self,
        input: &str,
        context: &ExecutionContext,
    ) -> Result<ExecutionResult> {
        let mut attempt = 0;

        loop {
            attempt += 1;

            match self.execute(input, context).await {
                Ok(result) if result.output.is_success() => {
                    return Ok(result);
                }

                Ok(result) => {
                    if attempt >= self.config.max_retries {
                        return Ok(result);
                    }

                    // 生成修复提示
                    let healing_input = self.generate_healing_prompt(
                        input,
                        &result.output,
                        attempt,
                    );

                    // 递归调用（带修复提示）
                    return self.execute(&healing_input, context).await;
                }

                Err(e) => {
                    if attempt >= self.config.max_retries {
                        return Err(e);
                    }

                    // 指数退避
                    let backoff = Duration::from_millis(100 * 2u64.pow(attempt as u32));
                    tokio::time::sleep(backoff).await;
                }
            }
        }
    }
}
```

**设计要点**：
- **三层路由**：反射层（毫秒级）→ 推理层（秒级）→ 自愈循环（多次尝试）
- **自学习机制**：成功的推理自动加入反射层，逐步提升命中率
- **向后兼容**：通过 `try_convert_to_atomic` 实现渐进式迁移

