//! FileEditTool - Incremental file editing with 80-95% token savings
//!
//! This tool implements the core innovation of the atomic engine: incremental
//! editing via patches, which dramatically reduces token consumption compared
//! to traditional full-file writes.
//!
//! # Token Efficiency
//!
//! - Traditional file_write: ~5000 tokens (for 200-line file)
//! - file_edit with patches: ~200 tokens (only modified lines)
//! - **Savings: 96%**
//!
//! # Example
//!
//! ```json
//! {
//!   "tool": "file_edit",
//!   "path": "src/main.rs",
//!   "patches": [
//!     {
//!       "start_line": 42,
//!       "end_line": 45,
//!       "old_content": "fn old_function() {\n    // old code\n}",
//!       "new_content": "fn new_function() {\n    // new code\n}"
//!     }
//!   ]
//! }
//! ```

use async_trait::async_trait;
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::path::Path;
use tracing::{info, warn};

use crate::builtin_tools::error::ToolError;
use crate::engine::{Patch, PatchApplier};
use crate::error::Result;
use crate::tools::AlephTool;

/// File edit tool for incremental editing
#[derive(Clone)]
pub struct FileEditTool {
    /// Maximum file size for edit operations (10MB default)
    max_file_size: u64,
}

impl FileEditTool {
    /// Tool identifier
    pub const NAME: &'static str = "file_edit";

    /// Tool description for AI prompt
    pub const DESCRIPTION: &'static str = r#"Incrementally edit files using patches. This is MUCH more token-efficient than rewriting entire files.

WHEN TO USE:
- Modifying specific lines in a file (e.g., fixing a bug, updating a function)
- Making multiple changes to different parts of a file
- Any edit where you know the exact line numbers to change

TOKEN EFFICIENCY:
- Traditional file_write: ~5000 tokens (for 200-line file)
- file_edit: ~200 tokens (only modified lines)
- Savings: 80-95%

PATCH FORMAT:
Each patch specifies:
- start_line: First line to replace (1-indexed)
- end_line: Last line to replace (1-indexed, inclusive)
- old_content: Current content (for validation)
- new_content: New content to insert

VALIDATION:
- The tool verifies old_content matches the file before applying
- This prevents conflicts from concurrent modifications
- If validation fails, you'll get a clear error message

CONFLICT DETECTION:
- Patches with overlapping line ranges are automatically detected
- You'll get an error if patches conflict

EXAMPLE:
To change lines 10-12 in a file:
{
  "path": "src/main.rs",
  "patches": [{
    "start_line": 10,
    "end_line": 12,
    "old_content": "fn old() {\n    println!(\"old\");\n}",
    "new_content": "fn new() {\n    println!(\"new\");\n}"
  }]
}

PATH RESOLUTION:
- Relative paths → resolved to ~/.aleph/output/
- Home paths (~/) → expanded to user's home directory
- Absolute paths → used as-is

IMPORTANT: Always read the file first to get the correct line numbers and old_content!"#;

    /// Create a new FileEditTool with default settings
    pub fn new() -> Self {
        Self {
            max_file_size: 10 * 1024 * 1024, // 10MB
        }
    }

    /// Execute file edit operation (internal implementation)
    async fn call_impl(&self, args: FileEditArgs) -> std::result::Result<FileEditOutput, ToolError> {
        use crate::builtin_tools::{notify_tool_result, notify_tool_start};

        // Notify tool start
        let args_summary = format!("编辑文件: {} ({} patches)", &args.path, args.patches.len());
        notify_tool_start(Self::NAME, &args_summary);

        info!(
            path = %args.path,
            patch_count = args.patches.len(),
            "FileEditTool::call invoked"
        );

        let path = Path::new(&args.path);

        // Resolve path (using same logic as file_ops)
        let resolved_path = self.resolve_path(path)?;

        // Check file exists
        if !resolved_path.exists() {
            let error = ToolError::NotFound(format!("File not found: {}", resolved_path.display()));
            notify_tool_result(Self::NAME, false);
            return Err(error);
        }

        // Check file size
        let metadata = tokio::fs::metadata(&resolved_path)
            .await
            .map_err(|e| ToolError::IoError(format!("Failed to read file metadata: {}", e)))?;

        if metadata.len() > self.max_file_size {
            let error = ToolError::InvalidInput(format!(
                "File too large: {} bytes (max: {} bytes)",
                metadata.len(),
                self.max_file_size
            ));
            notify_tool_result(Self::NAME, false);
            return Err(error);
        }

        // Read file content
        let content = tokio::fs::read_to_string(&resolved_path)
            .await
            .map_err(|e| ToolError::IoError(format!("Failed to read file: {}", e)))?;

        // Apply patches
        let applier = PatchApplier::new(args.patches);

        // Detect conflicts
        let conflicts = applier.detect_conflicts();
        if !conflicts.is_empty() {
            let error = ToolError::InvalidInput(format!(
                "Patch conflicts detected: {:?}. Patches have overlapping line ranges.",
                conflicts
            ));
            notify_tool_result(Self::NAME, false);
            return Err(error);
        }

        // Apply all patches
        let new_content = applier
            .apply_all(&content)
            .map_err(|e| ToolError::InvalidInput(format!("Failed to apply patches: {}", e)))?;

        // Write back to file
        tokio::fs::write(&resolved_path, &new_content)
            .await
            .map_err(|e| ToolError::IoError(format!("Failed to write file: {}", e)))?;

        info!(
            path = %resolved_path.display(),
            patch_count = applier.len(),
            "File edited successfully"
        );

        notify_tool_result(Self::NAME, true);

        Ok(FileEditOutput {
            success: true,
            path: resolved_path.display().to_string(),
            patches_applied: applier.len(),
            message: format!(
                "Successfully applied {} patches to {}",
                applier.len(),
                resolved_path.display()
            ),
        })
    }

    /// Resolve path (same logic as file_ops)
    fn resolve_path(&self, path: &Path) -> std::result::Result<std::path::PathBuf, ToolError> {
        // If absolute path, use as-is
        if path.is_absolute() {
            return Ok(path.to_path_buf());
        }

        // If starts with ~, expand home directory
        if let Some(path_str) = path.to_str() {
            if path_str.starts_with("~/") || path_str == "~" {
                if let Some(home) = dirs::home_dir() {
                    let relative = path_str.strip_prefix("~/").unwrap_or("");
                    return Ok(home.join(relative));
                }
            }
        }

        // Otherwise, resolve to ~/.aleph/output/
        let output_dir = dirs::home_dir()
            .ok_or_else(|| ToolError::IoError("Failed to get home directory".to_string()))?
            .join(".aleph")
            .join("output");

        Ok(output_dir.join(path))
    }
}

impl Default for FileEditTool {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl AlephTool for FileEditTool {
    const NAME: &'static str = Self::NAME;
    const DESCRIPTION: &'static str = Self::DESCRIPTION;

    type Args = FileEditArgs;
    type Output = FileEditOutput;

    async fn call(&self, args: Self::Args) -> Result<Self::Output> {
        self.call_impl(args).await.map_err(Into::into)
    }

    fn requires_confirmation(&self) -> bool {
        // File edits are potentially destructive, but we trust the validation mechanism
        false
    }

    fn examples(&self) -> Option<Vec<String>> {
        Some(vec![
            "Edit a single line: {\"path\": \"config.toml\", \"patches\": [{\"start_line\": 5, \"end_line\": 5, \"old_content\": \"debug = false\", \"new_content\": \"debug = true\"}]}".to_string(),
            "Edit multiple lines: {\"path\": \"src/main.rs\", \"patches\": [{\"start_line\": 10, \"end_line\": 15, \"old_content\": \"old function body\", \"new_content\": \"new function body\"}]}".to_string(),
            "Multiple patches: {\"path\": \"README.md\", \"patches\": [{\"start_line\": 1, \"end_line\": 1, \"old_content\": \"# Old Title\", \"new_content\": \"# New Title\"}, {\"start_line\": 10, \"end_line\": 12, \"old_content\": \"old section\", \"new_content\": \"new section\"}]}".to_string(),
        ])
    }
}

/// Arguments for file_edit tool
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct FileEditArgs {
    /// Path to the file to edit
    pub path: String,

    /// List of patches to apply
    pub patches: Vec<Patch>,
}

/// Output from file_edit tool
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct FileEditOutput {
    /// Whether the operation succeeded
    pub success: bool,

    /// Resolved file path
    pub path: String,

    /// Number of patches applied
    pub patches_applied: usize,

    /// Success/error message
    pub message: String,
}

