    #[test]
    fn test_reflex_layer_learning() {
        let reflex = ReflexLayer::new();

        // Learn a new pattern
        let action = AtomicAction::Read {
            path: "config.toml".to_string(),
            range: None,
        };
        reflex.learn_from_success("show config", action.clone());

        // Should hit L1 cache
