async fn execute_with_retries(
    &self,
    action: AtomicAction,
    retry_count: usize,
) -> Result<ExecutionResult, AlephError> {
    // Try to execute the action
    let result = self.executor.execute(&action).await;

    match result {
        Ok(output) => Ok(ExecutionResult {
            success: true,
            message: output,
            suggested_fix: None,
        }),
        Err(e) if retry_count < self.max_retries => {
            // Attempt self-healing
            if let Some(fix) = self.suggest_fix(&action, &e).await {
                tracing::warn!(
                    "Execution failed (attempt {}/{}), trying fix: {:?}",
                    retry_count + 1,
                    self.max_retries,
                    fix
                );
                // Execute the fix
                let fix_result = self.executor.execute(&fix).await;
                if fix_result.is_ok() {
                    // Retry original action after fix
                    return self.execute_with_retries(action, retry_count + 1).await;
                }
            }
            // No fix available or fix failed
            Ok(ExecutionResult {
                success: false,
                message: e.to_string(),
                suggested_fix: None,
            })
        }
        Err(e) => Ok(ExecutionResult {
            success: false,
            message: e.to_string(),
            suggested_fix: None,
        }),
    }
}

