pub async fn route_query(&self, query: &str) -> RoutingResult {
    let reflex = self.reflex.read().await;

    // L1: Exact match (fastest)
    if let Some(action) = reflex.route_l1(query) {
        return RoutingResult {
            layer: RoutingLayer::L1,
            action,
            latency_ms: 0.0, // Will be measured by caller
        };
    }

    // L2: Keyword routing (fast)
    if let Some(action) = reflex.route_l2(query) {
        return RoutingResult {
            layer: RoutingLayer::L2,
            action,
            latency_ms: 0.0,
        };
    }

    // L3: Requires LLM reasoning (fallback)
    RoutingResult {
        layer: RoutingLayer::L3,
        action: None,
        latency_ms: 0.0,
    }
}

