    let reflex = self.reflex.read().await;
    let stats = reflex.stats();

    RoutingStats {
        l1_hits: stats.l1_hits as usize,
        l2_hits: stats.l2_hits as usize,
        l3_fallbacks: stats.l3_fallbacks as usize,
