/// Freeze a browser context (pause JavaScript execution)
///
/// This method sends a CDP Debugger.pause command to freeze JavaScript
/// execution in the specified task's browser context. This is used for
/// task preemption in the priority scheduler.
///
/// # Arguments
/// * `task_id` - The task ID whose context should be frozen
///
/// # Returns
/// * `Ok(())` if the context was successfully frozen
/// * `Err(BrowserError::NotStarted)` if the context doesn't exist
/// * `Err(BrowserError::ActionFailed)` if the CDP command fails
#[cfg(feature = "browser")]
pub async fn freeze_context(&self, task_id: &TaskId) -> BrowserResult<()> {
    // Get the context for this task
    let context = self.get_ephemeral_context(task_id).await
        .ok_or(BrowserError::NotStarted)?;

    // Send CDP Debugger.enable command first (required before pause)
    use chromiumoxide::cdp::browser_protocol::debugger::EnableParams;
    context.execute(EnableParams::default())
        .await
        .map_err(|e| BrowserError::ActionFailed(format!("Failed to enable debugger: {}", e)))?;

    // Send CDP Debugger.pause command
    use chromiumoxide::cdp::browser_protocol::debugger::PauseParams;
    context.execute(PauseParams::default())
        .await
        .map_err(|e| BrowserError::ActionFailed(format!("Failed to pause context: {}", e)))?;

    // Track frozen state
    self.frozen_contexts.write().await.insert(task_id.clone());

    tracing::info!("Frozen context for task: {}", task_id);
    Ok(())
}

