                anchor.id,
                anchor.rule_text,
                trigger_tags_json,
                anchor.confidence,
                anchor.created_at.to_rfc3339(),
                anchor.last_validated.to_rfc3339(),
                anchor.validation_count,
                anchor.failure_count,
                source_json,
                scope_json,
                anchor.priority,
                conflicts_with_json,
                anchor.supersedes,
            ],
        )?;

        Ok(())
    }

    /// Delete a behavioral anchor by ID
