    fn test_analyze_task_chain() {
        let (critic, _temp_dir) = setup_test_critic();

        let tool_sequence = vec![
            TaskStep {
                tool: "read_file".to_string(),
                parameters: "/test.txt".to_string(),
                result: Some("content".to_string()),
            },
            TaskStep {
                tool: "read_file".to_string(),
                parameters: "/test.txt".to_string(),
                result: Some("content".to_string()),
            },
        ];

        let exp = ExperienceBuilder::new(
