        store.add(anchor1).unwrap();
        store.add(anchor2).unwrap();
        store.add(anchor3).unwrap();

        let anchor_store = Arc::new(RwLock::new(store));
        let llm_config = LLMConfig {
            model: "claude-3-5-sonnet-20241022".to_string(),
