async fn test_complete_proactive_flow() {
    // Setup
    let db = create_test_db().await;
    let anchor_store = create_test_anchor_store();
    let scan_config = critic::CriticScanConfig::default();
    let llm_config = critic::LLMConfig::default();

    let critic_agent = CriticAgent::new(
        Arc::clone(&db),
        Arc::clone(&anchor_store),
        scan_config,
        llm_config,
    );

    // Create mock experience data
    let experience = create_test_experience();

    // Act: CriticAgent analyzes the experience
    let result = critic_agent.analyze_experience(&experience).await;

    // Assert: Analysis succeeds
    assert!(
        result.is_ok(),
        "Proactive analysis should succeed: {:?}",
        result.err()
    );

    let critic_report = result.unwrap();

    // Verify BehavioralAnchor properties
    let anchor = &critic_report.suggested_anchor;
    assert_eq!(
        anchor.priority, 50,
        "Proactive anchors should have priority 50"
    );
    assert_eq!(
        anchor.confidence, 0.6,
        "Proactive anchors should have confidence 0.6"
    );

    // Verify anchor source
    match &anchor.source {
        AnchorSource::ProactiveReflection {
            pattern_hash,
            optimization_type,
        } => {
            assert!(!pattern_hash.is_empty(), "Pattern hash should not be empty");
            assert!(
                !optimization_type.is_empty(),
                "Optimization type should not be empty"
            );
        }
        _ => panic!("Expected ProactiveReflection source"),
    }

    // Verify chain analysis
    assert!(
        critic_report.analysis.efficiency_score <= 1.0,
        "Efficiency score should be <= 1.0"
    );
    assert!(
        critic_report.analysis.efficiency_score >= 0.0,
        "Efficiency score should be >= 0.0"
    );

    // Store the anchor
    let mut store = anchor_store.write().unwrap();
    let store_result = store.add(anchor.clone());
    assert!(store_result.is_ok(), "Should be able to store anchor");
