async fn test_end_to_end_flow() {
    // Setup
    let db = create_test_db().await;
    let anchor_store = create_test_anchor_store();
    let llm_config = reactive::LLMConfig::default();

    // Step 1: Simulate a failure → ReactiveReflector → Store anchor
